SELECT PIPELINE_ID AS row_id, ACTIVE_FLAG AS active_flag, 'Y' AS well_formed, PIPELINE_CODE AS pipeline_code, PIPELINE_NAME AS pipeline_name, DESCRIPTION AS description, REFRESH_TYPE AS refresh_type, RUN_SCHEDULE AS run_schedule, SCHEDULE_TIMEZONE AS schedule_timezone, SCHEDULE_START_DATE AS schedule_start_date, CATCHUP AS catchup, MAX_CATCHUP_RUNS AS max_catchup_runs, OVERLAP_POLICY AS overlap_policy, MAX_PARALLEL_TASKS AS max_parallel_tasks, PRIORITY AS priority, BLOCK_ON_REFRESH_ERROR AS block_on_refresh_error, SLA_IN_HOURS AS sla_in_hours, PIPELINE_PARAMETERS AS pipeline_parameters FROM CFG_PIPELINES WHERE PROJECT_ID=:project_id ORDER BY 1
